body:
### What happens?

If I use the Python or C++ APIs alone to manipulate the database, memory control is normal. But when alternating between Python and C++ to querying the same database, the total memory usage seems to becoming at most 2x larger than setting. The following example contains three steps:
1. I set "memory_limit" to "2GB", create two tables (each one has 2 million rows and 100 columns) and concat two tables with "positional join" in Python. The maximum is nearly 2GB as expected. 
2. Then the program call C++ function in Python (use pybind11) to concat two tables in the same way. The memory usage reaches 4GB. (Note that if closing the Python's connection in the first step, the memory usage still reaches 3GB)
3. Finally, the program runs back to Python and concat two tables again, the memory usage also exceeds 2GB.
```
# 1. Call Python functions to create and concat tables
prepare_db()
print("Prepare table success!")
concat_test("tb1", "tb2")
print("Concat table success!")
# 2. Call C++ function to concat tables
duckdb_func.test_duckdb()
# 3. Call Python function to concat tables
concat_test("tb1", "tb2")
print("Concat new table success!")
```

### To Reproduce

*duckdb_func.cpp*
```
#include <iostream>
#include <memory>
#include <chrono>
#include <unistd.h>
#include <ios>
#include <fstream>
#include <string>
#include <thread>
#include "duckdb.hpp"

#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <pybind11/numpy.h>
#include <pybind11/operators.h>

using namespace std;

void process_mem_usage(double& vm_usage, double& resident_set)
{
   using std::ios_base;
   using std::ifstream;
   using std::string;

   vm_usage     = 0.0;
   resident_set = 0.0;

   // 'file' stat seems to give the most reliable results
   //
   ifstream stat_stream("/proc/self/stat",ios_base::in);

   // dummy vars for leading entries in stat that we don't care about
   //
   string pid, comm, state, ppid, pgrp, session, tty_nr;
   string tpgid, flags, minflt, cminflt, majflt, cmajflt;
   string utime, stime, cutime, cstime, priority, nice;
   string O, itrealvalue, starttime;

   // the two fields we want
   //
   unsigned long vsize;
   long rss;

   stat_stream >> pid >> comm >> state >> ppid >> pgrp >> session >> tty_nr
               >> tpgid >> flags >> minflt >> cminflt >> majflt >> cmajflt
               >> utime >> stime >> cutime >> cstime >> priority >> nice
               >> O >> itrealvalue >> starttime >> vsize >> rss; // don't care about the rest

   stat_stream.close();

   long page_size_kb = sysconf(_SC_PAGE_SIZE) / 1024; // in case x86-64 is configured to use 2MB pages
   vm_usage     = vsize / 1024.0;
   resident_set = rss * page_size_kb;
}

void test_duckdb() {
    auto monitor_thread = std::thread([&] () {
        double vm, rss;
        while (true) {
            process_mem_usage(vm, rss);
            cout << "[C++] start VM: " << vm << "; RSS: " << rss << endl;
            sleep(1);
        }
    });
    monitor_thread.detach();
    std::unordered_map<string, string> duckdb_config = { {"memory_limit", "2GB"}, {"threads", "2"} };
    duckdb::DBConfig config(duckdb_config, false);
    std::unique_ptr<duckdb::DuckDB> database = std::unique_ptr<duckdb::DuckDB>(new duckdb::DuckDB("testdb.db", &config));
    shared_ptr<duckdb::Connection> conn = std::make_shared<duckdb::Connection>(*database);
    for (int n = 0; n < 5; n++) {
        std::string sql = "drop table if exists table_" + std::to_string(n); 
        conn->Query(sql);
        sql = "create table table_" + std::to_string(n) + " as select * from tb1 positional join tb2";
        conn->Query(sql);
    }
}

PYBIND11_MODULE(duckdb_func, m) {
    m.def("test_duckdb", &test_duckdb);
}
```

*CMakeLists.txt*
```
cmake_minimum_required(VERSION 3.5.1)
project(duckdb_test)

add_definitions(-D_GLIBCXX_USE_CXX11_ABI=0)
set(CMAKE_CXX_STANDARD 17)
set(CMAKE_CXX_FLAGS "-std=c++17 ${CMAKE_CXX_FLAGS} -O3 -pthread")

Set(CMAKE_LIBRARY_OUTPUT_DIRECTORY "${CMAKE_BINARY_DIR}/lib/")
Set(CMAKE_RUNTIME_OUTPUT_DIRECTORY "${CMAKE_BINARY_DIR}/bin/")

IF(NOT CMAKE_BUILD_TYPE)
    set(CMAKE_BUILD_TYPE "Release")
ENDIF()
message(STATUS "CMAKE_BUILD_TYPE " ${CMAKE_BUILD_TYPE})

add_subdirectory(pybind11)
pybind11_add_module(duckdb_func duckdb_func.cpp)
target_link_libraries(duckdb_func PUBLIC ${CMAKE_CURRENT_SOURCE_DIR}/libduckdb.so)
```

*test.py*
```
import pandas as pd
import numpy as np
import logging, sys
import duckdb
import time
import psutil
import asyncio
import threading 
from jeddak_io import JIO
import duckdb_func

def monitor_memory_usage():
    max_memory = 0
    while True:
        process_memory_info = psutil.Process().memory_info()
        mem = process_memory_info.rss / 1024 / 1024
        if mem > max_memory: 
            max_memory = mem
        print(f'[Python] Memory usage: {mem} MB, max usage: {max_memory} MB')
        time.sleep(1)

t = threading.Thread(target=monitor_memory_usage)
t.setDaemon(True)
t.start()

engine = duckdb.connect("testdb.db", config={"memory_limit": "2GB", "threads": "2"})
test_file = '../jio_test/testdb.csv'

def prepare_db():
    engine.execute("drop table if exists tb1")
    engine.execute(f'create table tb1 as select * from "{test_file}"')
    engine.execute("drop table if exists tb2")
    engine.execute(f'create table tb2 as select * from "{test_file}"')

def concat_test(table_a, table_b):
    engine.execute("drop table if exists tb_concat")
    t1 = time.time()
    engine.execute(f'create table tb_concat as select * from {table_a} positional join {table_b}')
    t2 = time.time()
    print("concat time usage: ", t2 - t1)

# 1. Call Python functions to create and concat tables
prepare_db()
print("Prepare table success!")
concat_test("tb1", "tb2")
print("Concat table success!")
# 2. Call C++ function to concat tables
duckdb_func.test_duckdb()
# 3. Call Python function to concat tables
concat_test("tb1", "tb2")
print("Concat new table success!")
```

Run the following commands to build and test:
```
git clone https://github.com/duckdb/duckdb.git
git clone https://github.com/pybind/pybind11.git
mkdir build
cd build
cmake ..
make -j4 
cd ..
cp build/lib/duckdb_func* ./
python3 test.py
```

