### What happens?

Interface DatabaseMetaData provides these methods:

- supportsCatalogsInDataManipulation: "Retrieves whether a catalog name can be used in a data manipulation statement", see: https://docs.oracle.com/en/java/javase/11/docs/api/java.sql/java/sql/DatabaseMetaData.html#supportsCatalogsInDataManipulation()
- supportsCatalogsInIndexDefinitions: "Retrieves whether a catalog name can be used in an index definition statement."  https://docs.oracle.com/en/java/javase/11/docs/api/java.sql/java/sql/DatabaseMetaData.html#supportsCatalogsInIndexDefinitions()
- supportsCatalogsInTableDefinitions: "Retrieves whether a catalog name can be used in a table definition statement." https://docs.oracle.com/en/java/javase/11/docs/api/java.sql/java/sql/DatabaseMetaData.html#supportsCatalogsInTableDefinitions()

The respective implementations in DuckDBDatabaseMetaData always return false. 

I believe they should return true, as duckdb lets you use catalog qualified names to manipulate objects in attached databases. 

### To Reproduce

Test for https://docs.oracle.com/en/java/javase/11/docs/api/java.sql/java/sql/DatabaseMetaData.html#supportsCatalogsInTableDefinitions():

```
	public static void test_supports_catalogs_in_table_definitions() throws Exception {
		final Connection connection = DriverManager.getConnection("jdbc:duckdb:");
		final Statement statement = connection.createStatement();
		final DatabaseMetaData databaseMetaData = connection.getMetaData();
		final String CATALOG_NAME = "tmp";
		final String TABLE_NAME = "t1";
		final String qualifiedTableName = CATALOG_NAME + "." + TABLE_NAME;
		ResultSet resultSet = null;
		try {
			final File file = Files.createTempFile("duckdb-jdbc-test-", ".duckdb").toFile();
			file.delete();
			statement.execute("ATTACH '" + file.getAbsolutePath() + "' AS \"" + CATALOG_NAME + "\"");
			file.deleteOnExit();

			final boolean supportsCatalogsInTableDefinitions = databaseMetaData.supportsCatalogsInTableDefinitions();
			try {
				statement.execute("CREATE TABLE " + qualifiedTableName + "(id int)");
			}
			catch (SQLException ex) {
				if (supportsCatalogsInTableDefinitions) {
					fail("supportsCatalogsInTableDefinitions is true but CREATE TABLE in attached database is not allowed.");
				}
			}
			resultSet = statement.executeQuery(
				"SELECT * FROM information_schema.tables "+
				"WHERE table_catalog = '" + CATALOG_NAME + "' " +
				"AND table_name = '" + TABLE_NAME + "' "
			);
			assertTrue(resultSet.next(), "Expected exactly 1 row from information_schema.tables, got 0");
			assertFalse(resultSet.next());
			resultSet.close();

			try {
				statement.execute("DROP TABLE " + qualifiedTableName);
			}
			catch (SQLException ex) {
				if (supportsCatalogsInTableDefinitions) {
					fail("supportsCatalogsInTableDefinitions is true but DROP TABLE in attached database is not allowed.");
				}
			}
			resultSet = statement.executeQuery(
				"SELECT * FROM information_schema.tables "+
				"WHERE table_catalog = '" + CATALOG_NAME + "' " +
				"AND table_name = '" + TABLE_NAME + "' "
			);
			assertTrue(resultSet.next() == false, "Expected exactly 0 rows from information_schema.tables, got > 0");
			resultSet.close();

			assertTrue(supportsCatalogsInTableDefinitions, "supportsCatalogsInTableDefinitions should return true.");
		} 
		finally {
			if (resultSet != null) {
				resultSet.close();
			}
			statement.close();
			connection.close();
		}
	}
```

Test for https://docs.oracle.com/en/java/javase/11/docs/api/java.sql/java/sql/DatabaseMetaData.html#supportsCatalogsInDataManipulation()

```
	public static void test_supports_catalogs_in_data_manipulation() throws Exception {
		final File file = Files.createTempFile("duckdb-jdbc-test-", ".duckdb").toFile();
		final String filePath = file.getAbsolutePath();
		final String CATALOG_NAME = "tmp";
		final String TABLE_NAME = "t1";
		final String qualifiedTableName = CATALOG_NAME + "." + TABLE_NAME;
		file.delete();
		Connection connection = null;
		Statement statement = null;

		connection = DriverManager.getConnection("jdbc:duckdb:" + filePath);
		file.deleteOnExit();
		statement = connection.createStatement();
		statement.execute("CREATE TABLE " + TABLE_NAME + "(id int)");
		statement.close();
		connection.close();

		Thread.currentThread().sleep(1000);

		connection = DriverManager.getConnection("jdbc:duckdb:");
		final DatabaseMetaData databaseMetaData = connection.getMetaData();
		statement = connection.createStatement();
		ResultSet resultSet = null;
		try {
			statement.execute("ATTACH '" + filePath + "' AS \"" + CATALOG_NAME + "\"");

			final boolean supportsCatalogsInDataManipulation = databaseMetaData.supportsCatalogsInDataManipulation();
			try {
				statement.execute("INSERT INTO " + qualifiedTableName + " VALUES(1)");
				resultSet = statement.executeQuery("SELECT * FROM "+ qualifiedTableName);
				assertTrue(resultSet.next(), "Expected exactly 1 row from " + qualifiedTableName + ", got 0");
				assertTrue(resultSet.getInt("ID") == 1, "Value for ID should be 1");
				resultSet.close();
			}
			catch (SQLException ex) {
				if (supportsCatalogsInDataManipulation) {
					fail("supportsCatalogsInDataManipulation is true but INSERT in " + qualifiedTableName + " is not allowed.");
				}
			}

			try {
				statement.execute("UPDATE " + qualifiedTableName + " SET ID = 2 WHERE ID = 1");
				resultSet = statement.executeQuery("SELECT * FROM "+ qualifiedTableName);
				assertTrue(resultSet.next(), "Expected exactly 1 row from " + qualifiedTableName + ", got 0");
				assertTrue(resultSet.getInt("ID") == 2, "Value for ID should be 2");
				resultSet.close();
			}
			catch (SQLException ex) {
				if (supportsCatalogsInDataManipulation) {
					fail("supportsCatalogsInDataManipulation is true but UPDATE of " + qualifiedTableName + " is not allowed.");
				}
			}

			try {
				statement.execute("DELETE FROM " + qualifiedTableName + " WHERE ID = 2");
				resultSet = statement.executeQuery("SELECT * FROM "+ qualifiedTableName);
				assertTrue(resultSet.next() == false, "Expected 0 rows from " + qualifiedTableName + ", got > 0");
				resultSet.close();
			}
			catch (SQLException ex) {
				if (supportsCatalogsInDataManipulation) {
					fail("supportsCatalogsInDataManipulation is true but UPDATE of " + qualifiedTableName + " is not allowed.");
				}
			}

			assertTrue(supportsCatalogsInDataManipulation, "supportsCatalogsInDataManipulation should return true.");
		} 
		finally {
			if (resultSet != null) {
				resultSet.close();
			}
			statement.close();
			connection.close();
		}
	}
