                             BFTableFilterState &state) const {
+	if (!filter.IsReady()) {
+		return approved_tuple_count;
+	}
 	if (state.current_capacity < approved_tuple_count) {
 		state.hashes_v.Initialize(false, approved_tuple_count);
 		state.bf_sel.Initialize(approved_tuple_count);
@@ -131,6 +139,9 @@
 }

