  area(x: number, y: number): string;
}
```

### 🙁 Actual behavior

```ts
class ShapeImpl implements Shape {
  // ❌
  area(_x: number, _y?: number): number | string {
    return 0;
  }
}

function createShape(): Shape {
  return {
    // ❌
